def _resources_misses() -> dict:
    try:
        body = json.loads(RESOURCES_MISS_FILE.read_text())
        return _fresh_misses(body) if isinstance(body, dict) else {}
    except Exception:
        return {}


def _resources_note(key: str, missed: bool) -> None:
    try:
        body = _resources_misses()
        row = body.get(key) if isinstance(body.get(key), dict) else {}
        body[key] = {"misses": (int(row.get("misses", 0) or 0) + 1) if missed else 0,
                     "last": time.time()}
        RESOURCES_MISS_FILE.parent.mkdir(parents=True, exist_ok=True)
        RESOURCES_MISS_FILE.write_text(json.dumps(body, indent=1, sort_keys=True))
    except Exception:
        pass


def _rest_left(row, limit: int, rest_seconds: float) -> float:
    """Seconds a miss record {"misses", "last"} still rests its place for:
    0.0 under `limit` misses in a row, or once `rest_seconds` have passed."""
    if not isinstance(row, dict) or int(row.get("misses", 0) or 0) < limit:
        return 0.0
    left = rest_seconds - (time.time() - float(row.get("last", 0.0) or 0.0))
    return max(0.0, left)


def _resources_resting(key: str, limit: int, rest_seconds: float) -> float:
    """Seconds this place still rests for, 0.0 when it may be tried."""
    return _rest_left(_resources_misses().get(key), limit, rest_seconds)


