def _respawn_view_offset(frame) -> float | None:
    """Pixels between this frame's view and the nearer standard one, or None
    when it cannot be measured (no frame, no reference)."""
    try:
        import numpy as np
        if not _respawn_view_refs:
            for path in RESPAWN_VIEWS:
                ref = cv2.imread(str(path))
                if ref is not None:
                    _respawn_view_refs.append(cv2.cvtColor(
                        ref[150:520, :, :3], cv2.COLOR_BGR2GRAY).astype(np.float32))
        if frame is None or not _respawn_view_refs:
            return None
        cur = cv2.cvtColor(frame[150:520, :, :3], cv2.COLOR_BGR2GRAY).astype(np.float32)
        window = cv2.createHanningWindow((cur.shape[1], cur.shape[0]), cv2.CV_32F)
        best = None
        for ref in _respawn_view_refs:
            if ref.shape != cur.shape:
                continue
            (dx, dy), response = cv2.phaseCorrelate(ref, cur, window)
            if best is None or response > best[1]:
                best = (max(abs(dx), abs(dy)), response, (float(dx), float(dy)))
        _respawn_view_shift[0] = None if best is None else best[2]
        return None if best is None else float(best[0])
    except Exception:
        return None


def _load_cannon_record() -> dict:
    # A RECORD KEPT UNDER ANOTHER APPROACH STARTS AFRESH. The misses are
    # evidence against the approach that made them, and the grounding below
    # (CANNON_RETRY_SECONDS x misses, to six hours) would otherwise keep a
    # changed approach walking for hours after a deploy: MEASURED 2026-09-25
    # 23:50, var/cannon.json held misses 4, last_try 23:45:30 and no approach
    # named -- the six-hour cap, grounding every flight until 05:45 for the
    # ten hops act/routes no longer does (DESIGN 8dl). The fresh record is
    # written at once, so this is said once. The name to match is
    # act/routes.CANNON_APPROACH_VERSION.
    fresh = {"misses": 0, "last_try": 0.0, "landed": 0,
             "approach": CANNON_APPROACH_VERSION}
    try:
        body = json.loads(CANNON_RECORD_FILE.read_text())
        if isinstance(body, dict):
            record = {"misses": int(body.get("misses", 0) or 0),
                      "last_try": float(body.get("last_try", 0.0) or 0.0),
                      "landed": int(body.get("landed", 0) or 0),
                      "approach": CANNON_APPROACH_VERSION}
            if body.get("approach") == CANNON_APPROACH_VERSION:
                return record
            print(f"    the red cannon's record ({record['misses']} miss(es)) was "
                  f"kept under {body.get('approach') or 'the ten-hop approach'} — "
                  f"starting it afresh for {CANNON_APPROACH_VERSION}", flush=True)
            _save_cannon_record(fresh)
            return dict(fresh)
    except Exception:
        pass
    return dict(fresh)


def _save_cannon_record(record: dict) -> None:
    try:
        CANNON_RECORD_FILE.parent.mkdir(parents=True, exist_ok=True)
        CANNON_RECORD_FILE.write_text(json.dumps(record, indent=1))
    except Exception:
        pass

