        def tunnelbear_due() -> bool:
            """The Tunnel Bear fought now (act/tunnelbear): combat.bosses on,
            its time come, enough bees read, and a walk's own conditions
            (shop_look_due). Mirrors crab_due()."""
            if tunnelbear_box["tried"] or stop.is_set() or inp.stale:
                return False

            def skip(why: str) -> bool:
                if tunnelbear_box["said"] != why:
                    tunnelbear_box["said"] = why
                    narrate(Log(message=f"Tunnel Bear: not now — {why}", source="errands"))
